  function validateLessons(lessons){return lessons.filter(lesson=>{const valid=lesson.id&&lesson.titleSw&&lesson.titleEn&&lesson.summary&&lesson.comprehensive&&lesson.source?.url&&lesson.source.verificationStatus==='verified';if(!valid){console.warn('Invalid lesson disabled:',lesson.id);lesson.active=false;return false}return lesson.active!==false})}
