  function normalizeAnswer(value){return String(value||'').toUpperCase().trim().replace(/\s+/g,' ').replace(/[^A-Z0-9 ]/g,'')}
  function validateQuestionBank(questions){const seen=new Set();return questions.filter(question=>{const hasQuestion=question.questionSw&&question.questionEn;const hasAnswer=question.answer||(question.options&&question.options.length);const hasSource=question.source&&question.source.url&&question.source.verificationStatus==='verified';const duplicateKey=`${normalizeAnswer(question.questionSw)}|${normalizeAnswer(question.answer)}|${question.category}`;if(!hasQuestion||!hasAnswer||!hasSource||seen.has(duplicateKey)){console.warn('Question disabled because it is incomplete, duplicated or unverified:',question.id);question.active=false;return false}seen.add(duplicateKey);return question.active!==false})}
  function resetGame(){gameState=clone(defaultGameState);saveGameState();renderApp();showScreen('welcome-screen');toast('Maendeleo yameanza upya.')}
  function prefersReducedMotion(){return gameState.settings.reducedMotion||window.matchMedia('(prefers-reduced-motion: reduce)').matches}
  function showScreen(id){const target=$(id);if(!target){console.error('Screen not found:',id);return}if(timerId&&id!=='game-screen') stopTimer();if(frameId&&id!=='game-screen') stopMovement();$$('.app-screen').forEach(s=>{s.classList.remove('active');s.setAttribute('aria-hidden','true')});target.classList.add('active');target.setAttribute('aria-hidden','false');activeScreen=id;window.scrollTo({top:0,behavior:prefersReducedMotion()?'auto':'smooth'});}
  function toast(message){const el=$('toast');if(!el)return;el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2200)}
  function playTone(kind='tap'){if(!gameState.settings.soundEnabled)return;try{const ctx=playTone.ctx||(playTone.ctx=new AudioContext());const osc=ctx.createOscillator(),gain=ctx.createGain();const tones={tap:420,correct:720,wrong:170,win:900,swallow:120};osc.frequency.value=tones[kind]||420;osc.type='sine';gain.gain.setValueAtTime(.035,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.16);osc.connect(gain).connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+.17)}catch(e){console.warn('Audio unavailable')}}
  function initializeNavigation(){document.addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(action) handleAction(action)});document.addEventListener('keydown',e=>{if(activeScreen==='game-screen'&&e.key==='Escape')handleAction(gameState.gamePaused?'resume':'pause');if(activeScreen==='game-screen'&&['Enter',' '].includes(e.key)&&e.target.classList.contains('letter-ball')){e.preventDefault();e.target.click()}})}
  function handleAction(action){playTone();const actions={welcome:()=>showScreen('welcome-screen'),howto:()=>showScreen('how-to-play-screen'),profile:()=>{populateProfile();showScreen('player-profile-screen')},start:()=>beginFromProfile(),continue:()=>{showScreen('level-map-screen');renderLevelMap()},map:()=>{showScreen('level-map-screen');renderLevelMap()},library:()=>{renderLibrary();showScreen('learning-library-screen')},settings:()=>{renderSettings();showScreen('settings-screen')},achievements:()=>{renderAchievements();showScreen('achievements-screen')},leaderboard:()=>{renderLeaderboard();showScreen('leaderboard-screen')},pause:pauseGame,resume:resumeGame,'restart-question':restartQuestion,'next-question':nextQuestion,'retry-question':retryQuestion,'retry-level':()=>startLevel(gameState.currentLevel),'next-level':()=>startLevel(Math.min(3,gameState.currentLevel+1)),submit:submitAnswer,hint:useHint,'clear-last':clearLast,'clear-answer':clearAnswer,source:openSource,about:()=>showScreen('about-screen'),reset:()=>{if(confirm('Futa maendeleo yote ya mchezo?'))resetGame()},'toggle-sound':toggleSound};if(actions[action])actions[action]();else if(action.startsWith('level-'))startLevel(Number(action.split('-')[1]))}
  function initializePlayerProfile(){const regionEl=$('region');if(regionEl)regionEl.innerHTML='<option value="">Chagua mkoa</option>'+regions.map(r=>`<option>${r}</option>`).join('');$('profile-form')?.addEventListener('submit',e=>{e.preventDefault();gameState.player.name=$('player-name').value.trim()||'Mjenzi';gameState.player.gender=$('gender').value;gameState.player.region=$('region').value;saveGameState();renderMapPlayer();showScreen('level-map-screen');renderLevelMap();toast('Wasifu umehifadhiwa!')})}
  function populateProfile(){$('player-name').value=gameState.player.name;$('gender').value=gameState.player.gender||'';$('region').value=gameState.player.region;const picker=$('avatar-picker');picker.innerHTML=avatars.map((a,i)=>`<button type="button" class="avatar-option ${gameState.player.avatar===`avatar-${i+1}`?'selected':''}" data-avatar="avatar-${i+1}" aria-label="Avatar ${i+1}">${a}</button>`).join('');picker.querySelectorAll('[data-avatar]').forEach(b=>b.onclick=()=>{gameState.player.avatar=b.dataset.avatar;picker.querySelectorAll('.avatar-option').forEach(x=>x.classList.remove('selected'));b.classList.add('selected')})}
  function renderApp(){if(gameState.player.name)$('continue-btn')?.classList.remove('hidden');renderMapPlayer();renderSettings();renderAchievements();renderLeaderboard();renderLibrary();}
  function renderMapPlayer(){const el=$('map-player');if(el)el.innerHTML=`${avatars[(Number((gameState.player.avatar||'avatar-1').split('-')[1])-1)%avatars.length]} ${gameState.player.name||'Mgeni'} · ${gameState.player.region||'Tanzania'}`}
  function beginFromProfile(){if(!gameState.player.name){populateProfile();showScreen('player-profile-screen')}else{showScreen('level-map-screen');renderLevelMap()}}
  function renderLevelMap(){renderMapPlayer();const el=$('level-map');if(!el)return;el.innerHTML=Object.entries(KZ_LEVELS).map(([num,level])=>{const n=Number(num),p=gameState.levelProgress[n],unlocked=gameState.unlockedLevels.includes(n),pct=Math.min(100,Math.round((p.total||0)/10*100));return `<article class="level-card ${unlocked?'active':'locked'}"><div class="level-node">${unlocked?'✦':'🔒'}</div><div><h3>Level ${n}: ${level.nameSw}</h3><p>${level.subtitle}</p><div class="level-progress"><span style="width:${pct}%"></span></div><div class="level-meta">${p.total||0}/10 maswali · ${p.stars||0} ★ · ${p.bestScore||0} pts</div></div><button class="level-action" data-action="level-${n}" ${unlocked?'':'disabled'}>${unlocked?'Cheza':'Funga'}</button></article>`}).join('')+'<div class="level-card" style="background:#e9f8f2"><div class="level-node">🐉</div><div><h3>Joka Kodi anakusubiri</h3><p>Jenga combo yako na jifunze neno jipya kila raundi.</p></div><span>↗</span></div>'}
  function startLevel(levelNumber){if(!gameState.unlockedLevels.includes(levelNumber)){toast('Kamilisha level iliyotangulia kwanza.');return}gameState.currentLevel=levelNumber;gameState.currentStage='easy';gameState.currentQuestionIndex=0;gameState.score=0;gameState.combo=0;gameState.bestCombo=0;gameState.lives=KZ_LEVELS[levelNumber].maxLives;gameState.hintsRemaining=3;gameState.gamePaused=false;sessionQuestions=questionBank.filter(q=>q.level===levelNumber&&!q.bonus).sort(()=>Math.random()-.5).slice(0,10);showScreen('game-screen');loadQuestion(sessionQuestions[0])}
  function loadQuestion(question){if(!question)return completeLevel();stopTimer();stopMovement();gameState.currentQuestion=question;gameState.selectedLetters=[];gameState.currentAnswer='';gameState.wrongSelections=0;gameState.hintUsed=false;gameState.gamePaused=false;const configuredTime=KZ_LEVELS[gameState.currentLevel].stages[question.stage]?.time||KZ_LEVELS[gameState.currentLevel].baseTime;gameState.timerRemaining=Math.max(10,configuredTime);const stage=KZ_LEVELS[gameState.currentLevel].stages[question.stage]||KZ_LEVELS[gameState.currentLevel].stages.easy;$('game-level-label').textContent=KZ_LEVELS[gameState.currentLevel].nameSw.toUpperCase();$('game-stage-label').textContent=`STAGE ${stage.label} · ${gameState.currentQuestionIndex+1}/10`;$('question-text').textContent=question.questionSw;$('question-subtext').textContent=question.questionEn;$('category-label').textContent=question.category;$('difficulty-label').textContent=question.stage==='easy'?'RAHISI':question.stage==='medium'?'KATI':'CHANGAMOTO';$('feedback-line').textContent='Gusa herufi sahihi kwa mpangilio.';updateTimerUI();buildAnswerSlots();buildLetterChain(question);startLetterMovement();startTimer();}
  function normalize(value){return String(value||'').toUpperCase().replace(/[^A-Z]/g,'')}
  function shuffle(array){return [...array].sort(()=>Math.random()-.5)}
  function buildAnswerSlots(){const q=gameState.currentQuestion,answer=q.type==='multiple-choice'?q.answer:normalize(q.answer),el=$('answer-slots');el.innerHTML=[...answer].map((_,i)=>`<span class="answer-slot" id="slot-${i}" aria-label="Nafasi ${i+1}">_</span>`).join('');$('answer-progress').textContent=`0 / ${q.type==='multiple-choice'?1:answer.length}`}
  function buildLetterChain(question){const layer=$('letter-layer');layer.innerHTML='';balls=[];const rawQueue=question.type==='multiple-choice'?shuffle(question.options||[]):shuffle(normalize(question.answer).split('').concat(shuffle(question.distractors||['A','R','X','P','M','O']).slice(0,Math.max(4,Math.min(7,normalize(question.answer).length+2)))));const safeSpacing=Math.min(.07,.62/Math.max(1,rawQueue.length-1));currentQueue=rawQueue.map((text,i)=>({text,index:i,progress:.06+i*safeSpacing,selected:false,isOption:question.type==='multiple-choice'}));currentQueue.forEach((ball,i)=>{const el=document.createElement('button');el.className='letter-ball';el.type='button';el.textContent=ball.text;el.style.setProperty('--ball',['#25A7F0','#18A66A','#F68B3C','#7c71e8'][i%4]);el.setAttribute('aria-label',`Chagua ${ball.text}`);el.dataset.index=i;el.onclick=()=>handleLetterSelection(ball,el);layer.appendChild(el);ball.el=el;balls.push(ball)});}
  function startLetterMovement(){lastFrame=performance.now();const level=KZ_LEVELS[gameState.currentLevel];const duration=Math.max(10,level.chainDuration||level.baseTime||10);const furthestBall=Math.max(...balls.map(ball=>ball.progress),.06);const speed=((.91-furthestBall)/(duration*1000))*level.letterSpeed;const loop=now=>{if(activeScreen!=='game-screen'||gameState.gamePaused){frameId=null;return}const dt=Math.min(40,now-lastFrame);lastFrame=now;balls.forEach(ball=>{if(!ball.selected){ball.progress+=dt*speed;positionBall(ball)}});const threat=balls.find(b=>!b.selected&&b.progress>.91);if(threat){handleQuestionFailure('dragon');return}frameId=requestAnimationFrame(loop)};frameId=requestAnimationFrame(loop)}
  function positionBall(ball){const svg=$('letter-path-svg'),path=$('letter-path');if(!ball.el||!path)return;const p=path.getPointAtLength(Math.max(0,Math.min(path.getTotalLength(),ball.progress*path.getTotalLength())));const rect=svg.getBoundingClientRect(),wrap=svg.parentElement.getBoundingClientRect();ball.el.style.left=`${(p.x/420)*rect.width + rect.left-wrap.left}px`;ball.el.style.top=`${(p.y/360)*rect.height + rect.top-wrap.top}px`}
  function stopMovement(){if(frameId){cancelAnimationFrame(frameId);frameId=null}}
  function handleLetterSelection(ball,el){if(gameState.gamePaused||!gameState.currentQuestion||ball.selected)return;playTone();const q=gameState.currentQuestion;if(q.type==='multiple-choice'){if(ball.text===q.answer){ball.selected=true;el.classList.add('selected');gameState.selectedLetters=[ball.text];updateAnswerSlots();submitAnswer()}else{wrongBall(ball,el)}return}const answer=normalize(q.answer),expected=answer[gameState.selectedLetters.length];if(ball.text===expected){ball.selected=true;el.classList.add('selected');gameState.selectedLetters.push(ball.text);updateAnswerSlots();$('feedback-line').textContent='Vizuri! Herufi inayofuata iko njiani.';if(gameState.selectedLetters.length===answer.length)submitAnswer()}else wrongBall(ball,el)}
  function wrongBall(ball,el){gameState.wrongSelections++;el.classList.remove('wrong');void el.offsetWidth;el.classList.add('wrong');$('feedback-line').textContent=KZ_COPY.sw.wrong;flashSlots();gameState.timerRemaining=Math.max(1,gameState.timerRemaining-KZ_LEVELS[gameState.currentLevel].wrongAnswerPenalty);updateTimerUI();if(gameState.wrongSelections>=3)handleQuestionFailure('mistakes')}
  function flashSlots(){const first=$('slot-'+gameState.selectedLetters.length)||$('slot-0');first?.classList.add('error');setTimeout(()=>first?.classList.remove('error'),450)}
  function updateAnswerSlots(){const q=gameState.currentQuestion,chosen=gameState.selectedLetters,answer=q.type==='multiple-choice'?[q.answer]:[...normalize(q.answer)];answer.forEach((_,i)=>{const slot=$('slot-'+i);if(!slot)return;slot.textContent=chosen[i]||'_';slot.classList.toggle('filled',Boolean(chosen[i]))});$('answer-progress').textContent=`${chosen.length} / ${q.type==='multiple-choice'?1:answer.length}`}
  function clearLast(){if(!gameState.selectedLetters.length)return;gameState.selectedLetters.pop();const ball=balls.find(b=>b.selected&&b.text===gameState.selectedLetters.at(-1));if(ball){ball.selected=false;ball.el.classList.remove('selected')}updateAnswerSlots()}
  function clearAnswer(){gameState.selectedLetters=[];balls.forEach(b=>{b.selected=false;b.el.classList.remove('selected')});updateAnswerSlots();$('feedback-line').textContent='Jibu limefutwa. Anza tena.'}
  function submitAnswer(){const q=gameState.currentQuestion;if(!q||!gameState.selectedLetters.length)return;const attempt=gameState.selectedLetters.join('');const correct=q.type==='multiple-choice'?attempt===q.answer:attempt===normalize(q.answer);if(correct)handleCorrectAnswer();else{wrongBall({text:''},{classList:{remove(){},add(){}}});toast('Kamilisha jibu kwa mpangilio sahihi.')}}
  function calculateQuestionScore({baseScore,remainingTime,maxTime,wrongSelections,hintUsed,combo}){const timeBonus=Math.round(baseScore*(remainingTime/maxTime)*.5),accuracyBonus=wrongSelections===0?50:0,hintPenalty=hintUsed?25:0,comboBonus=combo*10;return Math.max(10,baseScore+timeBonus+accuracyBonus+comboBonus-hintPenalty-wrongSelections*10)}
  function handleCorrectAnswer(){stopTimer();stopMovement();playTone('correct');const q=gameState.currentQuestion,level=KZ_LEVELS[gameState.currentLevel],earned=calculateQuestionScore({baseScore:q.type==='multiple-choice'?120:100,remainingTime:gameState.timerRemaining,maxTime:level.baseTime,wrongSelections:gameState.wrongSelections,hintUsed:gameState.hintUsed,combo:gameState.combo});gameState.score+=earned;gameState.totalXP+=Math.round(earned/5);gameState.combo++;gameState.bestCombo=Math.max(gameState.bestCombo,gameState.combo);gameState.levelProgress[gameState.currentLevel].correct++;gameState.levelProgress[gameState.currentLevel].total++;unlockAchievements(q);saveGameState();showResult(true,earned)}
  function showResult(correct,earned=0){const q=gameState.currentQuestion,card=$('result-card');card.classList.toggle('wrong',!correct);$('result-icon').textContent=correct?'✓':'!';$('result-kicker').textContent=correct?'HONGERA!':'JIBU SAHIHI';$('result-title').textContent=correct?'Jibu sahihi!':'Endelea kujifunza';$('result-answer').innerHTML=`Jibu: <strong>${q.answer}</strong>`;$('result-explanation').textContent=q.explanationSw;$('result-stats').innerHTML=correct?`<span class="stat"><b>+${earned}</b>Alama</span><span class="stat"><b>×${gameState.combo}</b>Combo</span><span class="stat"><b>+${Math.round(earned/5)}</b>XP</span>`:`<span class="stat"><b>${gameState.lives}</b>Maisha</span><span class="stat"><b>${q.sourceLabel}</b>Chanzo</span>`;$('result-primary').textContent=correct?'Swali linalofuata →':'Jaribu tena';$('result-primary').dataset.action=correct?'next-question':'retry-question';showScreen('question-result-screen');if(correct)confettiBurst()}
  function nextQuestion(){const nextIndex=gameState.currentQuestionIndex+1;if(nextIndex>=10){completeLevel();return}gameState.currentQuestionIndex=nextIndex;const next=sessionQuestions[nextIndex];gameState.currentStage=next.stage;showScreen('game-screen');loadQuestion(next)}
  function retryQuestion(){showScreen('game-screen');loadQuestion(gameState.currentQuestion)}
  function handleQuestionFailure(reason){if(!gameState.currentQuestion||activeScreen!=='game-screen')return;stopTimer();stopMovement();gameState.lives--;gameState.combo=0;gameState.levelProgress[gameState.currentLevel].total++;gameState.currentQuestionIndex=Math.min(gameState.currentQuestionIndex,9);balls.forEach(b=>b.el.classList.add('selected'));playTone('swallow');$('feedback-line').textContent=KZ_COPY.sw.dragon;const dragon=$('game-dragon');dragon.classList.add('swallow');gameState.levelProgress[gameState.currentLevel].wrong=(gameState.levelProgress[gameState.currentLevel].wrong||0)+1;saveGameState();if(gameState.lives<=0){setTimeout(()=>{showGameOver();},650)}else{setTimeout(()=>showResult(false),650)}}
  function showGameOver(){$('game-over-stats').innerHTML=`<span class="stat"><b>${gameState.score}</b>Alama</span><span class="stat"><b>${gameState.levelProgress[gameState.currentLevel].correct||0}</b>Sahihi</span><span class="stat"><b>${gameState.totalXP}</b>XP</span>`;showScreen('game-over-screen')}
  function startTimer(){stopTimer();timerId=setInterval(()=>{if(gameState.gamePaused)return;gameState.timerRemaining--;updateTimerUI();if(gameState.timerRemaining<=0)handleQuestionFailure('time')},1000)}
  function stopTimer(){if(timerId){clearInterval(timerId);timerId=null}}
  function updateTimerUI(){const val=Math.max(0,gameState.timerRemaining);$('timer-value').textContent=val;$('timer-chip').classList.toggle('warning',val<=5)}
